# md2a: convert MIT format signal files to AHA DB distribution tape format.
#
# The files generated by this program are in the format formerly used for
# distribution of the AHA and MIT-BIH databases on half-inch 9-track digital
# tape. It does *not* generate files in the format currently used for
# distribution of the AHA database on floppy disk; ad2m can perform the
# reverse conversion, however.
#
# This file is part of WFDB-x, an independent reimplementation of the WFDB
# Software Package in Python, C++, MATLAB/Octave, Rust, Julia, R and Kotlin.
#
# It is a Julia translation of convert/md2a.c from the WFDB Software Package
# 10.7.0, by George B. Moody. The translation follows the logic and behavior of
# the original program, but it is new code, not the original C code.
#
# Changes from the original: none, apart from the language and the --legacy
# option (as the first argument, it restores the original behavior).
#
# Original C program: convert/md2a.c, WFDB Software Package 10.7.0.
#   Copyright (C) 2001 George B. Moody.
# Julia translation and changes: Copyright (C) 2026 Reza Sameni.
#
# This program is free software: you can redistribute it and/or modify it
# under the terms of the GNU General Public License as published by the Free
# Software Foundation, either version 3 of the License, or (at your option)
# any later version. See LICENSE.

const _MD2A_EODF = Int32(0o100000)   # AHA data file end-of-data marker
const _MD2A_FMT = Int32(16)          # AHA tape signal files are in format 16

const _MD2A_HELP = (
    "usage: %s -o AHAFILE -r RECORD [ OPTIONS ... ]\n",
    "where AHAFILE is the name of the AHA-format output signal file,",
    "RECORD is the record name, and OPTIONS may include:",
    " -h         print this usage summary",
    " -n NEWREC  create a header file for the output signal file, so it",
    "             may be read as record NEWREC")

function md2a_main(args::Vector{String})
    # WFDB-x: --legacy as the first argument selects legacy mode (the
    # behavior of the original program; see wfdbx_legacy_args)
    wfdbx_legacy_args(args)
    argv = cargs(args)              # C argv[i] (i >= 1) is argv[i]
    argc = length(argv) + 1
    pname = "md2a"
    nrec = ofname = record = nothing
    s = [Siginfo() for _ in 1:WFDB_MAXSIG]

    i = 1
    while i < argc
        a = argv[i]
        if _annapp_c0(a) == UInt8('-')
            c = _annapp_c1(a)
            if c == UInt8('h')          # help requested
                _annapp_help(pname, _MD2A_HELP)
                cexit(1)
            elseif c == UInt8('n')      # new record name follows
                i += 1
                if i >= argc
                    ceprintf("%s: new record name must follow -n\n", pname)
                    cexit(1)
                end
                nrec = argv[i]
            elseif c == UInt8('o')      # output file name follows
                i += 1
                if i >= argc
                    ceprintf("%s: name of AHA-format output file must follow -o\n", pname)
                    cexit(1)
                end
                ofname = argv[i]
            elseif c == UInt8('r')      # record name follows
                i += 1
                if i >= argc
                    ceprintf("%s: record name must follow -r\n", pname)
                    cexit(1)
                end
                record = argv[i]
            else
                ceprintf("%s: unrecognized option %s\n", pname, a)
                cexit(1)
            end
        else
            ceprintf("%s: unrecognized argument %s\n", pname, a)
            cexit(1)
        end
        i += 1
    end
    if ofname === nothing || record === nothing
        _annapp_help(pname, _MD2A_HELP)
        cexit(1)
    end

    # Give up unless at least one input signal is readable.
    nsig = isigopen(record, s, WFDB_MAXSIG)
    nsig < 1 && cexit(2)

    # Check that the new record name is legal before proceeding. Note that
    # this step creates a header file in the current directory which is
    # overwritten below, after the processing is completed.
    nrec !== nothing && newheader(nrec) < 0 && cexit(3)

    # Set the output signal specifications.
    for k in 1:nsig
        s[k].fname = copy(ofname)
        s[k].desc = UInt8[]
        s[k].group = 0
        s[k].fmt = _MD2A_FMT
    end

    # Give up if the output cannot be written.
    osigfopen(s, nsig) < nsig && cexit(4)

    # Copy the input to the output. Reformatting is handled by putvec().
    # x has one element per output sample of a frame (at least
    # WFDB_MAXSIG); getvec sets the first nsig, the others stay zero. (In
    # C, x is an uninitialized array of WFDB_MAXSIG; see "Undefined
    # behaviors" in docs/KNOWN_C_BEHAVIORS.md.)
    nout = sum(max(s[k].spf, 1) for k in 1:nsig)
    x = zeros(Int32, max(nout, WFDB_MAXSIG))
    while getvec(x) == nsig && putvec(x) == nsig
    end

    # Write the new header file if requested.
    nrec !== nothing && newheader(nrec)

    # Write the end-of-data marker.
    x[1:nsig] .= _MD2A_EODF
    putvec(x)

    # Clean up.
    wfdbquit()
    cexit(0)
end

register_workload("md2a") do
    with_workload_data() do dir
        workload_tool("md2a", "-r", "100s", "-o", "out.aha", "-n", "outaha")
        workload_tool("md2a", "-r", "fmt16", "-o", "out.aha")
        workload_tool("md2a", "-r", "nosuch", "-o", "out.aha")
        workload_tool("md2a", "-r", "100s", "-o", "out.aha", "-n", "bad*name")
        workload_tool("md2a", "-h")
        workload_tool("md2a", "-q")
        workload_tool("md2a", "x")
    end
end
